   "text": "志誠進行一項中學生在某星期內用於做家課的時數的調查。在發出的問卷中，有二十份回覆。下面的幹葉圖顯示該二十份問卷記錄得的時數：\n\n| 幹（十位） | 葉（個位） |\n|:---:|:---|\n| 1 | 0　0　1　1　2　3　4　5　5　6　6　7　7 |\n| 2 | 0　0　0　5　8 |\n| 3 | 4　6 |\n\n(a)　求該二十份問卷記錄得的時數的平均值及中位數。（2 分）\n\n(b)　志誠再收到四份問卷。他知道這四份問卷記錄得的時數的平均值為 18。現知道四份問卷其中兩份記錄得的時數為 19 及 20。\n\n　　(i)　寫出該二十四份問卷記錄得的時數的平均值。\n\n　　(ii)　該二十四份問卷記錄得的時數的中位數與 (a) 所求得的中位數有沒有可能相同？試解釋你的答案。（4 分）",
   "html": "<p>志誠進行一項中學生在某星期內用於做家課的時數的調查。在發出的問卷中，有二十份回覆。下面的幹葉圖顯示該二十份問卷記錄得的時數：</p>\n<table>\n<thead>\n<tr>\n<th style=\"text-align: center;\">幹（十位）</th>\n<th style=\"text-align: left;\">葉（個位）</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td style=\"text-align: center;\">1</td>\n<td style=\"text-align: left;\">0　0　1　1　2　3　4　5　5　6　6　7　7</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">2</td>\n<td style=\"text-align: left;\">0　0　0　5　8</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">3</td>\n<td style=\"text-align: left;\">4　6</td>\n</tr>\n</tbody>\n</table>\n<p>(a)　求該二十份問卷記錄得的時數的平均值及中位數。（2 分）</p>\n<p>(b)　志誠再收到四份問卷。他知道這四份問卷記錄得的時數的平均值為 18。現知道四份問卷其中兩份記錄得的時數為 19 及 20。</p>\n<p>(i)　寫出該二十四份問卷記錄得的時數的平均值。</p>\n<p>(ii)　該二十四份問卷記錄得的時數的中位數與 (a) 所求得的中位數有沒有可能相同？試解釋你的答案。（4 分）</p>",
