   "text": "已知 $x^2+p \\equiv (x+2)(x+q)+10$，求 $p$。\n\n$$(x+2)(x+q)+10 = x^2+(q+2)x+2q+10$$\n\n比較 $x$ 項係數（左方無 $x$ 項）：\n\n$$q+2 = 0 \\;\\Rightarrow\\; q=-2$$\n\n比較常數項：\n\n$$p = 2q+10 = 2(-2)+10 = 6$$\n\n**答案：C　$p=6$**",
   "html": "<p>已知 $x^2+p \\equiv (x+2)(x+q)+10$，求 $p$。</p>\n<p>$$(x+2)(x+q)+10 = x^2+(q+2)x+2q+10$$</p>\n<p>比較 $x$ 項係數（左方無 $x$ 項）：</p>\n<p>$$q+2 = 0 \\;\\Rightarrow\\; q=-2$$</p>\n<p>比較常數項：</p>\n<p>$$p = 2q+10 = 2(-2)+10 = 6$$</p>\n<p><strong>答案：C　$p=6$</strong></p>",
