   "html": "<p>$x^3+4x^2+kx-12$ 可被 $x+3$ 整除，求 $k$。</p>\n<p>因式定理：$f(-3)=0$</p>\n<p>$$(-3)^3+4(-3)^2-3k-12 = 0$$</p>\n<p>$$-27+36-3k-12 = 0 \\;\\Rightarrow\\; -3-3k = 0 \\;\\Rightarrow\\; k=-1$$</p>\n<p><strong>答案：B　$k=-1$</strong></p>",
