   "html": "<p>設 $m+2n+6 = 2m-n = 7$，求 $n$。</p>\n<p>拆成兩式：</p>\n<p>$$m+2n = 1 \\quad (1)$$\n$$2m-n = 7 \\quad (2)$$</p>\n<p>$(1)\\times 2 - (2)$：</p>\n<p>$$5n = -5 \\;\\Rightarrow\\; n=-1$$</p>\n<p><strong>答案：B　$n=-1$</strong></p>",
