   "html": "<p>解 $15+4x&lt;3$ 或 $9-2x&gt;1$。</p>\n<p>$$15+4x&lt;3 \\;\\Rightarrow\\; 4x&lt;-12 \\;\\Rightarrow\\; x&lt;-3$$</p>\n<p>$$9-2x&gt;1 \\;\\Rightarrow\\; -2x&gt;-8 \\;\\Rightarrow\\; x&lt;4$$</p>\n<p>「或」= 取併集，包住兩者：</p>\n<p>$$x&lt;4$$</p>\n<p><strong>答案：C　$x&lt;4$</strong></p>",
