   "text": "袋中有 $7,8,8,9,9,9$ 六球，不放回地抽，直到抽到 $9$ 為止。求**恰好抽三次**的概率。\n\n恰好三次 ⇔ 首兩次非 9、第三次是 9：\n\n$$P = \\frac{3}{6}\\times\\frac{2}{5}\\times\\frac{3}{4} = \\frac{3}{20}$$\n\n**答案：D　$\\dfrac{3}{20}$**",
   "html": "<p>袋中有 $7,8,8,9,9,9$ 六球，不放回地抽，直到抽到 $9$ 為止。求<strong>恰好抽三次</strong>的概率。</p>\n<p>恰好三次 ⇔ 首兩次非 9、第三次是 9：</p>\n<p>$$P = \\frac{3}{6}\\times\\frac{2}{5}\\times\\frac{3}{4} = \\frac{3}{20}$$</p>\n<p><strong>答案：D　$\\dfrac{3}{20}$</strong></p>",
