   "html": "<p>化簡 $h\\ell-k\\ell+hm-km-hn+kn$。</p>\n<p>$$=(h-k)\\ell+(h-k)m-(h-k)n=(h-k)(\\ell+m-n)$$</p>\n<p><strong>答案：D　$(h-k)(\\ell+m-n)$</strong></p>",
