   "text": "設 $f(x)=4x^3-5x^2-18x+c$，其中 $c$ 為一常數。當 $f(x)$ 除以 $x-2$ 時，餘數為 $-33$。\n\n(a)　$x+1$ 是否 $f(x)$ 的因式？試解釋你的答案。\n\n(b)　某人宣稱方程 $f(x)=0$ 所有的根均為有理數。你是否同意？試解釋你的答案。（5 分）",
