   "text": "點 $P$ 及點 $Q$ 的坐標分別為 $(-3,5)$ 及 $(2,-7)$。$P$ 繞原點 $O$ 逆時針方向旋轉 $270^\\circ$ 至 $P'$。$Q$ 向左平移 $21$ 單位至 $Q'$。\n\n(a)　寫出 $P'$ 及 $Q'$ 的坐標。\n\n(b)　證明 $PQ$ 垂直於 $P'Q'$。（5 分）",
   "html": "<p>點 $P$ 及點 $Q$ 的坐標分別為 $(-3,5)$ 及 $(2,-7)$。$P$ 繞原點 $O$ 逆時針方向旋轉 $270^\\circ$ 至 $P'$。$Q$ 向左平移 $21$ 單位至 $Q'$。</p>\n<p>(a)　寫出 $P'$ 及 $Q'$ 的坐標。</p>\n<p>(b)　證明 $PQ$ 垂直於 $P'Q'$。（5 分）</p>",
