   "text": "A firm has an independent legal entity but the owners cannot transfer their ownership without the consent of the other owners. When the owners want to expand the firm's business, they can \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_.\n\n(1) use the retained profit of the firm\n\n(2) issue shares to the public to raise capital\n\n(3) borrow from friends to raise capital\n\n- A. (1) and (2) only\n- B. (1) and (3) only\n- C. (2) and (3) only\n- D. (1), (2) and (3)",
   "html": "<p>A firm has an independent legal entity but the owners cannot transfer their ownership without the consent of the other owners. When the owners want to expand the firm's business, they can __________.</p>\n<p>(1) use the retained profit of the firm</p>\n<p>(2) issue shares to the public to raise capital</p>\n<p>(3) borrow from friends to raise capital</p>\n<ul>\n<li>A. (1) and (2) only</li>\n<li>B. (1) and (3) only</li>\n<li>C. (2) and (3) only</li>\n<li>D. (1), (2) and (3)</li>\n</ul>",
