   "text": "If the nominal interest rate is 5% and the expected inflation rate is 3%, the cost of holding money is \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_, the nominal return of holding money is \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_ and the expected real interest rate is \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_.\n\n- A. 5% ...... −3% ...... 2%\n- B. 5% ...... 0% ...... 2%\n- C. 8% ...... −3% ...... 3%\n- D. 8% ...... 0% ...... 3%",
