   "html": "<p>The supply curve of a certain good is upward-sloping in a small open economy. What is the main difference between imposing an effective import quota and a tariff on the good?</p>\n<ul>\n<li>A. Imposing an effective import quota will lower the volume of import while imposing a tariff will not.</li>\n<li>B. Imposing an effective import quota will result in a rise in consumer surplus of the good while imposing a tariff may not.</li>\n<li>C. Imposing a tariff will raise the world price of the good while imposing an effective import quota will not.</li>\n<li>D. Imposing a tariff will result in an increase in the government revenue while imposing an effective import quota may not.</li>\n</ul>",
