   "text": "In the case **WITHOUT** tax exemption, John needs to pay $15\\,000$ and Mary needs to pay $35\\,000$ as income tax.\n\nSuppose the government proposes the following income tax exemption measures:\n\n| | Amount of tax exemption |\n|---|---|\n| Measure I | 75% of income tax, maximum $30\\,000$ |\n| Measure II | 100% of income tax, maximum $20\\,000$ |\n\nJohn will prefer \\_\\_\\_\\_\\_\\_ while Mary will prefer \\_\\_\\_\\_\\_\\_.\n\n- A. measure I ...... measure I\n- B. measure I ...... measure II\n- C. measure II ...... measure I\n- D. measure II ...... measure II",
   "html": "<p>In the case <strong>WITHOUT</strong> tax exemption, John needs to pay $15\\,000$ and Mary needs to pay $35\\,000$ as income tax.</p>\n<p>Suppose the government proposes the following income tax exemption measures:</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>Amount of tax exemption</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Measure I</td>\n<td>75% of income tax, maximum $30\\,000$</td>\n</tr>\n<tr>\n<td>Measure II</td>\n<td>100% of income tax, maximum $20\\,000$</td>\n</tr>\n</tbody>\n</table>\n<p>John will prefer ______ while Mary will prefer ______.</p>\n<ul>\n<li>A. measure I ...... measure I</li>\n<li>B. measure I ...... measure II</li>\n<li>C. measure II ...... measure I</li>\n<li>D. measure II ...... measure II</li>\n</ul>",
